ALTER TABLE accounts ADD COLUMN email TEXT;
CREATE UNIQUE INDEX accounts_email ON accounts(email) WHERE email IS NOT NULL;
ALTER TABLE podcasts ADD COLUMN public_catalog INTEGER NOT NULL DEFAULT 0;
ALTER TABLE podcasts ADD COLUMN prewarm INTEGER NOT NULL DEFAULT 0;
ALTER TABLE podcasts ADD COLUMN category TEXT NOT NULL DEFAULT 'Podcasts';
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, auth_method TEXT NOT NULL);
CREATE INDEX sessions_account ON sessions(account_id);
CREATE TABLE auth_challenges (id_hash TEXT PRIMARY KEY, challenge TEXT NOT NULL, purpose TEXT NOT NULL, account_id TEXT REFERENCES accounts(id) ON DELETE CASCADE, expires_at INTEGER NOT NULL);
CREATE TABLE passkeys (id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE, public_key TEXT NOT NULL, counter INTEGER NOT NULL DEFAULT 0, transports TEXT NOT NULL DEFAULT '[]', name TEXT NOT NULL, created_at INTEGER NOT NULL, last_used_at INTEGER, device_type TEXT NOT NULL, backed_up INTEGER NOT NULL DEFAULT 0);
CREATE INDEX passkeys_account ON passkeys(account_id);
CREATE TABLE directory_results (id TEXT PRIMARY KEY, feed_url TEXT NOT NULL, title TEXT NOT NULL, author TEXT NOT NULL, artwork TEXT NOT NULL, expires_at INTEGER NOT NULL);
